select coalesce(jsonb_agg(t.failed),'[]'::jsonb)as failures from (select 'ece:official:equipment:es:656acc5366e5b282988b132f' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:656acc5366e5b282988b132f' and payload#>'{features}'=$verify_8bd213ea78ae1ebe$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"De este collar cuelgan 1d6 + 3 cuentas. Puedes usar una acción para tirar una de estas cuentas a un punto a 18 m o menos de distancia. Cuando llegue al final de su trayectoria, la cuenta explotará como si fuera un conjuro bola de fuego de nivel 3 (CD de salvación 15).\n\nPuedes arrojar varias cuentas o incluso todo el collar en una acción. Si lo haces, aumenta el nivel de la bola de fuego en 1 por cada cuenta lanzada tras la primera.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_8bd213ea78ae1ebe$::jsonb and revision=3) union all select 'ece:official:equipment:es:65b77c0aa953b874822fa87d' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:65b77c0aa953b874822fa87d' and payload#>'{features}'=$verify_833b89a0b7bc1930$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras este cuenco esté lleno de agua, podrás utilizar una acción para pronunciar su palabra de activación e invocar un elemental de agua, como si hubieras lanzado conjurar elemental. El cuenco no puede volver a emplearse de esta manera hasta el siguiente amanecer.\n\nEl cuenco tiene aproximadamente 30 cm de diámetro y la mitad de profundidad. Pesa 1,5 kg y puede contener unos 12 l.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_833b89a0b7bc1930$::jsonb and revision=3) union all select 'ece:official:equipment:es:669dbf2489ed293bb38d8a17' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:669dbf2489ed293bb38d8a17' and payload#>'{features}'=$verify_77d5fd2152d45fa4$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro contiene ejercicios de coordinación y equilibrio, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Destreza aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_77d5fd2152d45fa4$::jsonb and revision=3) union all select 'ece:official:equipment:es:670193d18fadb992218eedf7' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:670193d18fadb992218eedf7' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_22cd2279e0ae6955$[{"id":"official-base-table","rows":[["Martillo de guerra","15 po","2 lb","1d8 contundente","+0","Versátil","1d10"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Daño versátil"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-versatile","text":"Versátil. Estas armas pueden utilizarse con una o con dos manos. Tras esta propiedad aparece entre paréntesis un valor de daño, que será el que uses cuando emplees esta arma a dos manos para hacer un ataque cuerpo a cuerpo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_22cd2279e0ae6955$::jsonb and revision=3) union all select 'ece:official:equipment:es:6717fd92ac73e3765596e309' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6717fd92ac73e3765596e309' and payload#>'{description}'=$verify_f7f023db0ab2a01d$"Objeto · Precio base · Peso\nAljaba · 1 po · 1 lb\n\nAljaba. Una aljaba puede contener hasta 20 flechas.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_f7f023db0ab2a01d$::jsonb and payload#>'{features}'=$verify_ad95de5033aa8476$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Aljaba. Una aljaba puede contener hasta 20 flechas.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_ad95de5033aa8476$::jsonb and payload#>'{rules,definition,description}'=$verify_2553e910a16c7cd4$[{"id":"official-table","rows":[["Aljaba","1 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Aljaba. Una aljaba puede contener hasta 20 flechas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_2553e910a16c7cd4$::jsonb and revision=3) union all select 'ece:official:equipment:es:67c4d58203382e9febe67247' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:67c4d58203382e9febe67247' and payload#>'{features}'=$verify_3e0d16b332934568$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes este bastón, tendrás resistencia al daño de frío.\n\nEl bastón tiene 10 cargas. Mientras lo empuñes, podrás usar una acción y gastar 1 o más de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros: cono de frío (5 cargas), muro de hielo (4 cargas), nube de oscurecimiento (1 carga) o tormenta de hielo (4 cargas).\n\nEl bastón recupera 1d6 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón se convierte en agua y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_3e0d16b332934568$::jsonb and revision=3) union all select 'ece:official:equipment:es:6807f943647e5f66904aab8c' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6807f943647e5f66904aab8c' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_c94309a253cab68c$[{"id":"official-base-table","rows":[["Cimitarra","25 po","3 lb","1d6 cortante","+0","Sutil, Ligera"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-finesse","text":"Sutil. Cuando ataques con un arma sutil, podrás elegir realizar las tiradas de ataque y de daño con el modificador por Fuerza o con el modificador por Destreza. Eso sí, deberás usar el mismo modificador para ambas tiradas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_c94309a253cab68c$::jsonb and revision=3) union all select 'ece:official:equipment:es:6880ccd9a4ad0a0ca9f7b45b' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6880ccd9a4ad0a0ca9f7b45b' and payload#>'{features}'=$verify_040b04c1d262cc65$[{"id":"legacy-bonus-0","kind":"passive","name":"All","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga un bono de +1 a todas las tiradas de salvación.","showInActions":false},{"id":"legacy-bonus-1","kind":"passive","name":"All","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga un bono de +1 a todas las pruebas de habilidad.","showInActions":false},{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":2,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta ágata pulida contigo, recibirás un bonificador de +1 a las pruebas de característica y las tiradas de salvación.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":3,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta ágata pulida contigo, recibirás un bonificador de +1 a las pruebas de característica y las tiradas de salvación.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_040b04c1d262cc65$::jsonb and revision=3) union all select 'ece:official:equipment:es:68d0af6495ab84438d9efff3' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:68d0af6495ab84438d9efff3' and payload#>'{features}'=$verify_938576b2bfb086c3$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para pronunciar la palabra de activación de este bastón y lanzarlo al suelo, a 3 m o menos de ti. El bastón se convertirá en una serpiente constrictora gigante bajo tu control y actuará en su propia posición en el orden de iniciativa. Si utilizas una acción adicional para pronunciar de nuevo la palabra de activación, el bastón recuperará su forma normal en un espacio que antes ocupaba la serpiente.\n\nEn tu turno, puedes dar órdenes mentales a la serpiente si se encuentra a 18 m o menos de ti y no estás incapacitado. Tú decides la acción que llevará a cabo la serpiente y adónde se desplazará durante su siguiente turno, o puedes darle una orden general, como atacar a tus enemigos o proteger un lugar.\n\nSi los puntos de golpe de la serpiente se reducen a 0, morirá y recuperará su forma de bastón. En tal caso, el bastón se hará añicos y se destruirá. Si la serpiente recupera la forma de bastón antes de perder todos sus puntos de golpe, los recuperará todos.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_938576b2bfb086c3$::jsonb and payload#>'{rules,personalDescription}'=$verify_9ecc9059b0bb2138$"Puedes usar una acción para decir la palabra de mando de este bastón y arrojarlo al suelo a 10 pies de ti. El bastón se convierte en una serpiente constrictora gigante bajo tu control y actúa por iniciativa propia. Al usar una acción adicional para decir la palabra de mando de nuevo, devuelves el bastón a su forma normal en un espacio que antes ocupaba la serpiente. \nEn tu turno, puedes ordenar mentalmente a la serpiente si está a 60 pies de ti y no estás incapacitado. Tú decides qué acción realiza la serpiente y adónde se mueve durante su próximo turno, o puedes darle una orden general, como atacar a tus enemigos o proteger una ubicación. \nSi la serpiente queda reducida a 0 puntos de golpe, muere y vuelve a su forma de bastón. Luego, el bastón se hace añicos y es destruido. Si la serpiente vuelve a su forma de bastón antes de perder todos sus puntos de golpe, los recupera todos."$verify_9ecc9059b0bb2138$::jsonb and revision=3) union all select 'ece:official:equipment:es:69d561ca2c3a56764e71cebd' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:69d561ca2c3a56764e71cebd' and payload#>'{features}'=$verify_b21f96047a351c1b$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro contiene consejos de salud y alimentación, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Constitución aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_b21f96047a351c1b$::jsonb and revision=3) union all select 'ece:official:equipment:es:6b4e8a7ee89714ac92465871' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6b4e8a7ee89714ac92465871' and payload#>'{description}'=$verify_5479001584507f1e$"Objeto · Precio base · Peso\nReloj de arena · 25 po · 1 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_5479001584507f1e$::jsonb and payload#>'{rules,definition,description}'=$verify_6188d493dbf01d15$[{"id":"official-table","rows":[["Reloj de arena","25 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_6188d493dbf01d15$::jsonb and revision=3) union all select 'ece:official:equipment:es:6bcfc9fa2fc699815dbbb59f' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6bcfc9fa2fc699815dbbb59f' and payload#>'{features}'=$verify_5efa713461f5b120$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Mientras lleves la espada contigo, también obtendrás un bonificador de +1 a las tiradas de salvación.\n\nDeseo. La espada tiene 1d4 – 1 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 carga y lanzar el conjuro deseo desde ella. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer. La espada pierde esta propiedad si no le quedan cargas.\n\nFortuna. Si llevas la espada contigo, puedes recurrir a su fortuna (no requiere acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación desfavorable. Deberás usar el nuevo resultado. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_5efa713461f5b120$::jsonb and payload#>'{rules,personalDescription}'=$verify_a7a069502542e9db$"Obtienes una bonificación de +1 a las tiradas de ataque y daño realizadas con esta arma mágica. Mientras la espada esté contigo, también obtienes una bonificación de +1 a las tiradas de salvación.\n\nSuerte. Si llevas la espada encima, puedes recurrir a su suerte (no es necesario realizar ninguna acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación que no te gusten. Debes utilizar la segunda tirada. Esta propiedad no se puede volver a utilizar hasta el siguiente amanecer.\n\nDeseo. La espada tiene 1d4–1 cargas. Mientras la sostienes, puedes usar una acción para gastar 1 carga y lanzar el conjuro de deseo desde ella. Esta propiedad no se puede volver a usar hasta el siguiente amanecer. La espada pierde esta propiedad si no tiene cargas."$verify_a7a069502542e9db$::jsonb and revision=3) union all select 'ece:official:equipment:es:6be205ff80da3f50db3b8036' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6be205ff80da3f50db3b8036' and payload#>'{features}'=$verify_5efa713461f5b120$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Mientras lleves la espada contigo, también obtendrás un bonificador de +1 a las tiradas de salvación.\n\nDeseo. La espada tiene 1d4 – 1 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 carga y lanzar el conjuro deseo desde ella. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer. La espada pierde esta propiedad si no le quedan cargas.\n\nFortuna. Si llevas la espada contigo, puedes recurrir a su fortuna (no requiere acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación desfavorable. Deberás usar el nuevo resultado. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_5efa713461f5b120$::jsonb and payload#>'{rules,personalDescription}'=$verify_a7a069502542e9db$"Obtienes una bonificación de +1 a las tiradas de ataque y daño realizadas con esta arma mágica. Mientras la espada esté contigo, también obtienes una bonificación de +1 a las tiradas de salvación.\n\nSuerte. Si llevas la espada encima, puedes recurrir a su suerte (no es necesario realizar ninguna acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación que no te gusten. Debes utilizar la segunda tirada. Esta propiedad no se puede volver a utilizar hasta el siguiente amanecer.\n\nDeseo. La espada tiene 1d4–1 cargas. Mientras la sostienes, puedes usar una acción para gastar 1 carga y lanzar el conjuro de deseo desde ella. Esta propiedad no se puede volver a usar hasta el siguiente amanecer. La espada pierde esta propiedad si no tiene cargas."$verify_a7a069502542e9db$::jsonb and revision=3) union all select 'ece:official:equipment:es:6c18c45b014bd495b9788c25' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6c18c45b014bd495b9788c25' and payload#>'{features}'=$verify_c177eb09f8c78bc3$[{"id":"critical-protection","kind":"passive","name":"Protección frente a críticos","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta armadura viene reforzada con adamantina, una de las sustancias más duras que existen. Mientras la lleves puesta, cualquier crítico contra ti se convierte en un impacto normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_c177eb09f8c78bc3$::jsonb and revision=3) union all select 'ece:official:equipment:es:6c22746b8f06e620d1547a10' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6c22746b8f06e620d1547a10' and payload#>'{features}'=$verify_700cde83ebc64f9c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Las piedras Ioun se llaman así por Ioun, un dios del conocimiento y la profecía adorado en algunos mundos. Existen muchos tipos de piedras Ioun, cada uno de ellos con una combinación distinta de forma y color.\n\nCuando utilices una acción para lanzar una de estas piedras al aire, la piedra girará alrededor de tu cabeza a una distancia de 1d3 × 30 cm y te otorgará un beneficio. A partir de entonces, otra criatura deberá utilizar una acción para agarrar o atrapar la piedra y separarla de ti, ya sea superando una tirada de ataque contra una CA de 24 o una prueba de Destreza (Acrobacias) con CD 24. Puedes utilizar una acción para tomar y guardar la piedra, lo que pone fin a su efecto.\n\nUna piedra tiene una CA de 24, 10 puntos de golpe y resistencia a todo el daño. Se considera un objeto vestido mientras gira alrededor de tu cabeza.\n\nAbsorción (muy rara). Mientras este elipsoide de color lila claro gire alrededor de tu cabeza, podrás usar tu reacción para cancelar un conjuro de nivel 4 o inferior lanzado por una criatura que puedas ver y que solo te haga objetivo a ti.\n\nEn cuanto la piedra haya cancelado 20 niveles de conjuros, se volverá gris porque su magia se habrá agotado. Si eres el objetivo de un conjuro cuyo nivel sea superior a la cantidad de niveles de conjuro que le queden a la piedra, no podrá cancelarlo.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_700cde83ebc64f9c$::jsonb and revision=3) union all select 'ece:official:equipment:es:6d0fa52287609369216948bf' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6d0fa52287609369216948bf' and payload#>'{features}'=$verify_ffeec24cc9187eb8$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nCuando impactes a un dragón con esta arma, este sufrirá 3d6 de daño adicional del tipo del arma. En lo que concierne a esta arma, “dragón” se refiere a cualquier criatura con el tipo “dragón”, incluidos seres como dragones tortuga y guivernos.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_ffeec24cc9187eb8$::jsonb and revision=3) union all select 'ece:official:equipment:es:6d448708b838897d955a51eb' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6d448708b838897d955a51eb' and payload#>'{description}'=$verify_025ea068512228e9$"Objeto · Precio base · Peso · Daño base · Propiedades · Bonificación mágica · Alcance normal/largo (pies)\nArco largo feroz · 50 po (solo objeto mundano base; no es el precio de la variante mágica) · 2 lb · 1d8 perforante · Munición, Pesada, A dos manos · +0 · 150/600\n\nCuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_025ea068512228e9$::jsonb and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_4bfc512a49fef2e9$[{"id":"official-table","rows":[["Arco largo feroz","50 po (solo objeto mundano base; no es el precio de la variante mágica)","2 lb","1d8 perforante","Munición, Pesada, A dos manos","+0","150/600"]],"type":"table","columns":["Objeto","Precio base","Peso","Daño base","Propiedades","Bonificación mágica","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"vicious-2014","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_4bfc512a49fef2e9$::jsonb and revision=3) union all select 'ece:official:equipment:es:6deba73e296507e887a4ed1f' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6deba73e296507e887a4ed1f' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_055d6faab42f5c07$[{"id":"official-base-table","rows":[["Lucero del alba","15 po","4 lb","1d8 perforante","+0","—"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_055d6faab42f5c07$::jsonb and revision=3) union all select 'ece:official:equipment:es:6e0e16ea21a0f01542022994' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6e0e16ea21a0f01542022994' and payload#>'{features}'=$verify_4a21ac4510aa7924$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta escoba de madera, que pesa 1,5 kg, funcionará como una escoba normal hasta que te montes en ella y pronuncies su palabra de activación. Entonces, levitará y podrás utilizarla para volar por el cielo. Tiene una velocidad volando de 15 m. Puede transportar hasta 200 kg, pero su velocidad volando se reduce a 9 m si transporta más de 100 kg. La escoba deja de levitar cuando aterrizas.\n\nPuedes ordenarle que viaje por sí misma a un lugar que esté a 1,5 km o menos de ti si pronuncias la palabra de activación, nombras el lugar y conoces el sitio en cuestión. La escoba regresará junto a ti cuando pronuncies otra palabra de activación mientras se encuentre a 1,5 km o menos de ti.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_4a21ac4510aa7924$::jsonb and revision=3) union all select 'ece:official:equipment:es:6e83c9fa1434c8e5af25720e' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6e83c9fa1434c8e5af25720e' and payload#>'{features}'=$verify_3eedc59bbdbb862b$[{"id":"mundane-assisted-use","kind":"other","name":"Contenido del paquete","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Paquete de artista (40 po). Incluye una mochila, un petate, 2 disfraces, 5 velas, raciones para 5 días, una cantimplora y útiles para disfrazarse.\n\nDuración: Según su uso..","showInActions":false}]$verify_3eedc59bbdbb862b$::jsonb and revision=3) union all select 'ece:official:equipment:es:6eaa83f8bf3b7833d32c8ec4' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6eaa83f8bf3b7833d32c8ec4' and payload#>'{features}'=$verify_fd3b1146f47c2c14$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta delgada candela está dedicada a una deidad y comparte su alineamiento. El alineamiento de la vela se puede percibir con el conjuro detectar el bien y el mal. Tu GM elige el dios y el alineamiento asociado o determina el alineamiento al azar.\n\n1–2 · Caótico malvado\n3–4 · Caótico neutral\n5–7 · Caótico bueno\n8–9 · Neutral malvado\n10–11 · Neutral\n12–13 · Neutral bueno\n14–15 · Legal malvado\n16–17 · Legal neutral\n18–20 · Legal bueno\n\nLa magia de la vela se activa al encenderla, lo que requiere una acción. Después de arder durante 4 horas, la vela se destruye. Puedes apagarla antes de que pase ese tiempo para seguir usándola después. Resta el tiempo que ha ardido del total, en intervalos de 1 minuto.\n\nMientras permanezca encendida, la vela emitirá luz tenue en un radio de 9 m. Todas las criaturas que estén dentro de ese radio y cuyo alineamiento coincida con el de la vela realizarán las tiradas de ataque, las tiradas de salvación y las pruebas de característica con ventaja. Además, un clérigo o druida dentro del radio de la luz y cuyo alinea- miento coincida con el de la vela podrá lanzar conjuros de nivel 1 que tenga preparados sin gastar espacios de conjuro. El efecto de estos conjuros será el mismo que si se hubieran lanzado con un espacio de conjuro de nivel 1.\n\nComo alternativa, la primera vez que enciendas la vela, podrás utilizarla para lanzar el conjuro portal. Hacer esto destruirá la vela.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_fd3b1146f47c2c14$::jsonb and payload#>'{rules,personalDescription}'=$verify_acf51c9c1082391b$"Esta candela delgada está dedicada a una deidad en concreto, por lo que comparte alineamiento con ella. Este último puede ser detectado con el conjuro detectar el bien y el mal. El DM elige el dios y el alineamiento asociado o lo determina al azar. La magia de la vela se activa al encenderla, lo que requiere una acción. Después de arder durante 4 horas, es destruida. Puedes apagarla antes de que pase este tiempo para seguir usándola después. Resta el tiempo que ha ardido del total, en intervalos de l minuto.\n\nMientras permanezca encendida, la vela producirá luz tenue en un radio de 30 pies. Cualquier criatura dentro de esta luz cuyo alineamiento coincida con el de la vela realizará las tiradas de ataque, salvación y pruebas de característica con ventaja. Además, un clérigo o druida dentro de la luz y cuyo alineamiento coincida con el de la vela podrá lanzar conjuros de nivel 1 que tenga preparados sin gastar espacios de conjuro. El efecto de estos conjuros será el mismo que si se hubieran lanzado con un espacio de conjuro de nivel l.\n\nDe forma alternativa, la primera vez que enciendas la vela puedes utilizarla para lanzar el conjuro portal. Hacer esto destruye la vela."$verify_acf51c9c1082391b$::jsonb and revision=3) union all select 'ece:official:equipment:es:6f505d7deed241155c4e0b85' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6f505d7deed241155c4e0b85' and payload#>'{features}'=$verify_8c07d2b3b737b96f$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro contiene ejercicios de lógica y memoria, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Inteligencia aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_8c07d2b3b737b96f$::jsonb and revision=3) union all select 'ece:official:equipment:es:711f85d63c831b6b0310fb58' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:711f85d63c831b6b0310fb58' and payload#>'{features}'=$verify_5efa713461f5b120$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Mientras lleves la espada contigo, también obtendrás un bonificador de +1 a las tiradas de salvación.\n\nDeseo. La espada tiene 1d4 – 1 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 carga y lanzar el conjuro deseo desde ella. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer. La espada pierde esta propiedad si no le quedan cargas.\n\nFortuna. Si llevas la espada contigo, puedes recurrir a su fortuna (no requiere acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación desfavorable. Deberás usar el nuevo resultado. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_5efa713461f5b120$::jsonb and payload#>'{rules,personalDescription}'=$verify_a7a069502542e9db$"Obtienes una bonificación de +1 a las tiradas de ataque y daño realizadas con esta arma mágica. Mientras la espada esté contigo, también obtienes una bonificación de +1 a las tiradas de salvación.\n\nSuerte. Si llevas la espada encima, puedes recurrir a su suerte (no es necesario realizar ninguna acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación que no te gusten. Debes utilizar la segunda tirada. Esta propiedad no se puede volver a utilizar hasta el siguiente amanecer.\n\nDeseo. La espada tiene 1d4–1 cargas. Mientras la sostienes, puedes usar una acción para gastar 1 carga y lanzar el conjuro de deseo desde ella. Esta propiedad no se puede volver a usar hasta el siguiente amanecer. La espada pierde esta propiedad si no tiene cargas."$verify_a7a069502542e9db$::jsonb and revision=3) union all select 'ece:official:equipment:es:72d78d4649313d1a3f8b5b1e' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:72d78d4649313d1a3f8b5b1e' and payload#>'{features}'=$verify_249d9877e6e0199e$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, tu puntuación de Fuerza cambiará durante 1 hora. El tipo de gigante determina la puntuación (consulta la tabla más adelante). La poción no tendrá ningún efecto si tu Fuerza es igual o superior a esa puntuación.\n\nEn el líquido transparente de la poción flota un trozo de uña de un gigante del tipo correspondiente. La poción de fuerza de gigante de escarcha y la poción de fuerza de gigante de piedra tienen el mismo efecto.\n\nGigante de las colinas · 21 · Infrecuente\nGigante de escarcha/piedra · 23 · Rara\nGigante de fuego · 25 · Rara\nGigante de las nubes · 27 · Muy rara\nGigante de las tormentas · 29 · Legendaria\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$verify_249d9877e6e0199e$::jsonb and revision=3) union all select 'ece:official:equipment:es:741c6683c6d99e0c4fd359ba' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:741c6683c6d99e0c4fd359ba' and payload#>'{description}'=$verify_383ecff6579ff2c0$"Objeto · Precio base · Peso\nAbrojos (bolsa de 20) · 1 po · 2 lb\n\nAbrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_383ecff6579ff2c0$::jsonb and payload#>'{features}'=$verify_816adba2fd0e635e$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Abrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_816adba2fd0e635e$::jsonb and payload#>'{rules,definition,description}'=$verify_ad9e1c5eb1c88758$[{"id":"official-table","rows":[["Abrojos (bolsa de 20)","1 po","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Abrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_ad9e1c5eb1c88758$::jsonb and revision=3) union all select 'ece:official:equipment:es:74a52ed7f52b736c3d425209' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:74a52ed7f52b736c3d425209' and payload#>'{features}'=$verify_75d1cfa2fedc4884$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este cubo mide 7,5 cm de lado e irradia una energía mágica palpable. Cada una de las seis caras del cubo está conectada con un plano de existencia diferente, entre ellos el Plano Material. El resto de planos los determina tu GM.\n\nPuedes utilizar una acción para pulsar un lado del cubo y lanzar el conjuro portal, de forma que se abra un portal hacia el plano conectado con esa cara. De forma alternativa, si utilizas una acción para pulsar una cara dos veces, puedes lanzar el conjuro desplazamiento entre planos (CD de salvación 17) con el cubo y transportar a los objetivos al plano conectado con esa cara.\n\nEl cubo tiene 3 cargas. Cada uso gasta 1 carga. El cubo recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_75d1cfa2fedc4884$::jsonb and revision=3) union all select 'ece:official:equipment:es:74d803c9be726373ff91c34e' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:74d803c9be726373ff91c34e' and payload#>'{features}'=$verify_84e82a45a64001fe$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. También tiene las propiedades adicionales que se mencionan a continuación. Cuando se utilice una de ellas, no podrá volver a usarse hasta el siguiente amanecer.\n\nGolpe relampagueante. Cuando impactes con un ataque cuerpo a cuerpo con el bastón, podrás hacer que el objetivo sufra 2d6 de daño de relámpago adicional.\n\nGolpe atronador. Cuando impactes con un ataque cuerpo a cuerpo con el bastón, podrás hacer que el bastón emita un chasquido atronador que se oiga a 90 m de distancia. El objetivo impactado deberá superar una tirada de salvación de Constitución con CD 17 o quedará aturdido hasta el final de tu siguiente turno.\n\nRelámpago. Puedes utilizar una acción para que un relámpago surja de la punta del bastón en una línea de 1,5 m de ancho y 36 m de largo. Todas las criaturas situadas en la línea deberán hacer una tirada de salvación de Destreza con CD 17; sufrirán 9d6 de daño de relámpago si la fallan o la mitad del daño si la superan.\n\nTrueno. Puedes utilizar una acción para hacer que el bastón emita un trueno ensordecedor que se oiga a 180 m de distancia. Todas las criaturas situadas a 18 m o menos de ti (menos tú) deberán realizar una tirada de salvación de Constitución con CD 17. Si la fallan, sufrirán 2d6 de daño de trueno y quedarán ensordecidas durante 1 minuto. Si la superan, sufrirán la mitad del daño y no quedarán ensordecidas.\n\nTruenos y relámpagos. Puedes utilizar una acción para usar las propiedades “relámpago” y “trueno” a la vez. Hacer esto no consume el uso diario de esas propiedades, solo de esta.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_84e82a45a64001fe$::jsonb and payload#>'{rules,personalDescription}'=$verify_337fb70cdceea982$"Este bastón se puede utilizar como un bastón mágico que otorga una bonificación de +2 a las tiradas de ataque y daño realizadas con él. También tiene las siguientes propiedades adicionales. Cuando se utiliza una de estas propiedades, no se puede volver a utilizar hasta el siguiente amanecer.\n\nRelámpago. Cuando realizas un ataque cuerpo a cuerpo con el bastón, puedes provocar que el objetivo sufra 2d6 puntos de daño por relámpago adicionales.\n\nTrueno. Cuando golpeas con un ataque cuerpo a cuerpo usando el bastón, puedes hacer que éste emita un trueno que se oye a 300 pies de distancia. El objetivo al que golpeas debe superar una tirada de salvación de Constitución CD 17 o quedará aturdido hasta el final de tu siguiente turno.\n\nGolpe de relámpago. Puedes usar una acción para hacer que un rayo salte desde la punta del bastón en una línea de 5 pies de ancho y 120 pies de largo. Cada criatura en esa línea debe realizar una tirada de salvación de Destreza CD 17, y si falla, recibe 9d6 puntos de daño por rayo, o la mitad de daño si tiene éxito.\n\nTrueno. Puedes usar una acción para hacer que el bastón emita un trueno ensordecedor, audible hasta 600 pies. Cada criatura a 60 pies de ti (sin incluirte a ti) debe realizar una tirada de salvación de Constitución CD 17. Si la tirada falla, la criatura recibe 2d6 puntos de daño por trueno y queda ensordeceda durante 1 minuto. Si la tirada tiene éxito, la criatura recibe la mitad del daño y no queda ensordeceda.\n\nTrueno y relámpago. Puedes usar una acción para usar las propiedades Golpe de relámpago y Atronador al mismo tiempo. Al hacerlo, no se consume el uso diario de esas propiedades, solo el uso de esta."$verify_337fb70cdceea982$::jsonb and revision=3) union all select 'ece:official:equipment:es:769ff7952f0ed75b062d6044' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:769ff7952f0ed75b062d6044' and payload#>'{features}'=$verify_bff3bb03f6016afe$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto de “agrandar” del conjuro agrandar/reducir durante 1d4 horas (no requiere concentración). El color rojo del líquido de la poción se expande continuamente a partir de una gota diminuta para teñir el líquido transparente que la rodea. A continuación, se vuelve a contraer. Si agitas la botella, no se interrumpirá el proceso.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_bff3bb03f6016afe$::jsonb and revision=3) union all select 'ece:official:equipment:es:77c1a86f7bceca1fb79453c1' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:77c1a86f7bceca1fb79453c1' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_80073a099c59bdfb$[{"id":"official-base-table","rows":[["Lanza","1 po","3 lb","1d6 perforante","+0","Arrojadiza, Versátil","20/60","1d8"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)","Daño versátil"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-versatile","text":"Versátil. Estas armas pueden utilizarse con una o con dos manos. Tras esta propiedad aparece entre paréntesis un valor de daño, que será el que uses cuando emplees esta arma a dos manos para hacer un ataque cuerpo a cuerpo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_80073a099c59bdfb$::jsonb and revision=3) union all select 'ece:official:equipment:es:784bd660a08f0f45bc4bd35e' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:784bd660a08f0f45bc4bd35e' and payload#>'{features}'=$verify_f8d4aa1b82e82ffc$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 o más de sus cargas para lanzar el conjuro proyectil mágico desde ella. Si empleas 1 carga, podrás lanzar la versión de nivel 1 del conjuro. Puedes aumentar el nivel del espacio de conjuro en 1 por cada carga adicional que emplees.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_f8d4aa1b82e82ffc$::jsonb and revision=3) union all select 'ece:official:equipment:es:787b7ce6af1d2525c342d664' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:787b7ce6af1d2525c342d664' and payload#>'{features}'=$verify_53c7703c439bc2cd$[{"id":"mundane-assisted-use","kind":"other","name":"Proyectiles de la bolsa","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"La bolsa contiene 20 balas de honda. El precio y peso corresponden a la bolsa completa.\n\nDuración: Según su uso..","showInActions":false}]$verify_53c7703c439bc2cd$::jsonb and revision=3) union all select 'ece:official:equipment:es:78a330dcbaa0773138491e90' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:78a330dcbaa0773138491e90' and payload#>'{features}'=$verify_4a48d0c039253fa2$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes usar una acción adicional para lanzar esta espada mágica al aire y pronunciar la palabra de activación. Cuando lo hagas, el arma comenzará a levitar, volará hasta 9 m y atacará a una criatura de tu elección que esté a 1,5 m o menos de ella. La espada utiliza tu tirada de ataque y tu modificador por característica para las tiradas de daño.\n\nMientras la espada esté levitando, podrás emplear una acción adicional para que vuele hasta 9 m hacia otro lugar situado a 9 m o menos de ti. Como parte de la misma acción adicional, podrás hacer que la espada ataque a una criatura situada a 1,5 m o menos de ella.\n\nDespués de que la espada flotante ataque por cuarta vez, volará hasta 9 m y tratará de regresar a tu mano. Si no tienes ninguna mano libre, caerá a tus pies. Si la espada tiene vía libre hasta ti, se te acercará todo lo que pueda y después caerá al suelo. También dejará de levitar si la agarras o si te alejas más de 9 m de ella.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_4a48d0c039253fa2$::jsonb and revision=3) union all select 'ece:official:equipment:es:79852c0176e7952ae8226dcc' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:79852c0176e7952ae8226dcc' and payload#>'{features}'=$verify_4a48d0c039253fa2$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes usar una acción adicional para lanzar esta espada mágica al aire y pronunciar la palabra de activación. Cuando lo hagas, el arma comenzará a levitar, volará hasta 9 m y atacará a una criatura de tu elección que esté a 1,5 m o menos de ella. La espada utiliza tu tirada de ataque y tu modificador por característica para las tiradas de daño.\n\nMientras la espada esté levitando, podrás emplear una acción adicional para que vuele hasta 9 m hacia otro lugar situado a 9 m o menos de ti. Como parte de la misma acción adicional, podrás hacer que la espada ataque a una criatura situada a 1,5 m o menos de ella.\n\nDespués de que la espada flotante ataque por cuarta vez, volará hasta 9 m y tratará de regresar a tu mano. Si no tienes ninguna mano libre, caerá a tus pies. Si la espada tiene vía libre hasta ti, se te acercará todo lo que pueda y después caerá al suelo. También dejará de levitar si la agarras o si te alejas más de 9 m de ella.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_4a48d0c039253fa2$::jsonb and revision=3) union all select 'ece:official:equipment:es:79a0a5ea6cf16922cb5a78f7' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:79a0a5ea6cf16922cb5a78f7' and payload#>'{features}'=$verify_57266ba65d589236$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nCuando impactes a un gigante con ella, el gigante sufrirá 2d6 de daño adicional del tipo del arma y deberá superar una tirada de salvación de Fuerza con CD 15 o caerá derribado. En lo que concierne a esta arma, “gigante” se refiere a cualquier criatura con el tipo “gigante”, incluidos seres como ettins y trolls.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_57266ba65d589236$::jsonb and revision=3) union all select 'ece:official:equipment:es:79ac3b7e18f9352b31f1cde4' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:79ac3b7e18f9352b31f1cde4' and payload#>'{features}'=$verify_f22a284ca7ab083d$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas botas forradas de pelaje son ceñidas y calentitas. Mientras las lleves puestas, obtendrás los siguientes beneficios: • Tienes resistencia al daño de frío. • El terreno difícil creado por hielo o nieve no te afecta. • Puedes aguantar temperaturas de hasta –45 °C sin más protección. Si llevas ropas pesadas, puedes soportar hasta –75 °C.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_f22a284ca7ab083d$::jsonb and payload#>'{rules,personalDescription}'=$verify_f7b471beabad753e$"Estas botas forradas de pelaje son ceñidas y calentitas. Mientras las lleves puestas, obtendrás los siguientes beneficios:\nResistencia al daño de frío.\nIgnoras el terreno difícil por nieve o hielo\nPuedes aguantar temperaturas de hasta -45 ºC sin más protección. Si llevas ropas pesadas, puedes soportar hasta - 75 ºC."$verify_f7b471beabad753e$::jsonb and revision=3) union all select 'ece:official:equipment:es:7a41873e8602ad756e91bf15' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7a41873e8602ad756e91bf15' and payload#>'{features}'=$verify_5d969e1c90876246$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este amuleto, podrás usar una acción para nombrar un lugar que conozcas de otro plano de existencia. Después, haz una prueba de Inteligencia con CD 15. Si la superas, lanzarás el conjuro desplazamiento entre planos. Si la fallas, tú y cualquier criatura y objeto que esté a 4,5 m o menos de ti os desplazaréis a un destino aleatorio. Tira 1d100. Si sacas entre 1 y 60, viajáis a un lugar aleatorio en el plano de existencia nombrado. Si sacas entre 61 y 100, aparecéis en un plano determinado al azar.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_5d969e1c90876246$::jsonb and revision=3) union all select 'ece:official:equipment:es:7c1a658894dfd5edf11c9260' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7c1a658894dfd5edf11c9260' and payload#>'{features}'=$verify_8b05c428c79f2f94$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta sustancia viscosa y blanca como la leche puede crear un vínculo adhesivo permanente entre dos objetos cualesquiera. Debe almacenarse en un bote o frasco que se haya untado con aceite escurridizo. En el momento de encontrar el recipiente, contendrá 30 g + 1d6 × 30 g.\n\n30 g de pegamento pueden cubrir una superficie cuadrada de 30 cm de lado. El pegamento tarda 1 minuto en asentarse. En cuanto lo haga, el vínculo que crea solo se puede romper si se aplica un disolvente universal o un aceite de etereidad o con un conjuro deseo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_8b05c428c79f2f94$::jsonb and payload#>'{rules,personalDescription}'=$verify_7c145f46337e29a5$"Esta sustancia viscosa y blanca como la leche es capaz de formar un vínculo adhesivo permanente entre dos objetos cualesquiera. Debe ser almacenada en un frasco o bote que haya sido untado con una capa de aceite escurridizo. En el momento de encontrar el recipiente, a este le quedarán 1d6 + 1 onzas.\n\nUna onza de pegamento puede cubrir una superficie de 1 pie cuadrado. Tarda un minuto en asentarse y hacer efecto. Una vez asentado, el vínculo creado solo puede romperse aplicando disolvente universal o aceite de etereidad, o mediante el conjuro deseo."$verify_7c145f46337e29a5$::jsonb and revision=3) union all select 'ece:official:equipment:es:7c5164541d5c7d2d1179ff8e' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7c5164541d5c7d2d1179ff8e' and payload#>'{features}'=$verify_447d1b12fca0c2f9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta vara de hierro posee un botón en uno de sus extremos. Puedes usar una acción para pulsar el botón y hacer que la vara se fije mágicamente en el sitio. Hasta que otra criatura o tú utilicéis una acción para pulsar de nuevo el botón, la vara no se moverá, desafiando a la gravedad si es necesario. Puede aguantar hasta 4000 kg de peso; una cantidad mayor provocará que se desactive y caiga. Una criatura puede usar su acción para realizar una prueba de Fuerza con CD 30. Si tiene éxito, moverá la vara hasta 3 m.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_447d1b12fca0c2f9$::jsonb and revision=3) union all select 'ece:official:equipment:es:7d150b153865ce199ca4823c' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7d150b153865ce199ca4823c' and payload#>'{description}'=$verify_13c2783a0f6c5ecf$"Objeto · Precio base · Peso\nAmuleto · 5 po · 1 lb\n\nSímbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_13c2783a0f6c5ecf$::jsonb and payload#>'{features}'=$verify_20d6da3fc6e17a06$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Símbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_20d6da3fc6e17a06$::jsonb and payload#>'{rules,definition,description}'=$verify_a2a80e2fdb6b3797$[{"id":"official-table","rows":[["Amuleto","5 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Símbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_a2a80e2fdb6b3797$::jsonb and revision=3) union all select 'ece:official:equipment:es:7d468487c373342123ec2cc0' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7d468487c373342123ec2cc0' and payload#>'{features}'=$verify_f754dbe1c023aca9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Las piedras Ioun se llaman así por Ioun, un dios del conocimiento y la profecía adorado en algunos mundos. Existen muchos tipos de piedras Ioun, cada uno de ellos con una combinación distinta de forma y color.\n\nCuando utilices una acción para lanzar una de estas piedras al aire, la piedra girará alrededor de tu cabeza a una distancia de 1d3 × 30 cm y te otorgará un beneficio. A partir de entonces, otra criatura deberá utilizar una acción para agarrar o atrapar la piedra y separarla de ti, ya sea superando una tirada de ataque contra una CA de 24 o una prueba de Destreza (Acrobacias) con CD 24. Puedes utilizar una acción para tomar y guardar la piedra, lo que pone fin a su efecto.\n\nUna piedra tiene una CA de 24, 10 puntos de golpe y resistencia a todo el daño. Se considera un objeto vestido mientras gira alrededor de tu cabeza.\n\nMaestría (legendaria). Mientras este prisma verde pálido gire alrededor de tu cabeza, tu bonificador por competencia aumenta en 1.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_f754dbe1c023aca9$::jsonb and revision=3) union all select 'ece:official:equipment:es:7e70af915a0f0151f102d0a1' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7e70af915a0f0151f102d0a1' and payload#>'{description}'=$verify_569cb37696c7d3eb$"Objeto · Precio base · Peso\nHerramientas de cartógrafo · 15 po · 6 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_569cb37696c7d3eb$::jsonb and payload#>'{features}'=$verify_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_2b2bca0e5c7a5789$::jsonb and payload#>'{rules,definition,description}'=$verify_08ae83fa509ef72d$[{"id":"official-table","rows":[["Herramientas de cartógrafo","15 po","6 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$verify_08ae83fa509ef72d$::jsonb and revision=4) union all select 'ece:official:equipment:es:7ed1857c411cd63b4a9ae3ec' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7ed1857c411cd63b4a9ae3ec' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_3bd2fbd4a29a4876$[{"id":"official-base-table","rows":[["Ballesta ligera","25 po","5 lb","1d8 perforante","+0","Munición, Recarga, A dos manos","80/320"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-ammunition","text":"Munición. Solo puedes realizar un ataque a distancia usando un arma con esta propiedad si tienes munición para ella. Cada vez que hagas un ataque, gastarás una unidad de munición. Extraer la munición de una aljaba, un estuche u otro contenedor forma parte del ataque (necesitas una mano libre para cargar un arma a una mano). Al final del combate, podrás recuperar la mitad de la munición usada si dedicas un minuto a buscar en el campo de batalla. Si empleas un arma con esta propiedad para hacer un ataque cuerpo a cuerpo, se considerará un arma improvisada (consulta “Armas improvisadas” en esta misma sección). Además, una honda deberá estar cargada para hacer daño cuando se utilice de esta forma.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-loading","text":"Recarga. Debido al tiempo que requiere recargar un arma con esta propiedad, cuando utilices una acción, acción adicional o reacción para atacar con ella, solo podrás disparar una unidad de munición, incluso aunque normalmente pudieras hacer más de un ataque.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_3bd2fbd4a29a4876$::jsonb and revision=3) union all select 'ece:official:equipment:es:7f88e7a006665acd21818ae9' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7f88e7a006665acd21818ae9' and payload#>'{features}'=$verify_94f1895779fee577$[{"id":"mundane-assisted-use","kind":"other","name":"Contenido del paquete","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Paquete de explorador de mazmorras (12 po). Incluye una mochila, una palanqueta, un martillo, 10 pitones, 10 antorchas, un yesquero, raciones para 10 días y una cantimplora. Además, el paquete tiene una cuerda de cáñamo de 15 m enganchada en un lado.\n\nDuración: Según su uso..","showInActions":false}]$verify_94f1895779fee577$::jsonb and revision=3) union all select 'ece:official:equipment:es:7fee756c80e074dd2dc47947' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7fee756c80e074dd2dc47947' and payload#>'{features}'=$verify_bb33c31630364152$[{"id":"legacy-bonus-0","kind":"passive","name":"PassivePerception","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +5 a la Percepción Pasiva mientras se usa y está sintonizado.","showInActions":false},{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas lentes de cristal cubren los ojos. Mientras las lleves puestas, tendrás ventaja en las pruebas de Sabiduría (Percepción) que dependan de la vista. En condiciones de buena visibilidad, podrás ver detalles de criaturas y objetos muy lejanos de incluso 60 cm de diámetro.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_bb33c31630364152$::jsonb and revision=3) union all select 'ece:official:equipment:es:81d0edc3f74b29c0545f788e' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:81d0edc3f74b29c0545f788e' and payload#>'{features}'=$verify_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_4ca76cc6ddf1af62$::jsonb and revision=3) union all select 'ece:official:equipment:es:821a97f9c8fb63e7bd326b70' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:821a97f9c8fb63e7bd326b70' and payload#>'{features}'=$verify_f0e511db536bffb9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Los puntos de golpe perdidos por el daño de esta arma solo pueden recuperarse mediante un descanso corto o largo, no mediante la regeneración, la magia o cualquier otro medio.\n\nUna vez por turno, cuando impactes a una criatura con un ataque usando esta arma mágica, podrás herirla. Al principio de cada turno de la criatura herida, sufrirá 1d4 de daño necrótico por cada vez que la hayas herido y luego podrá realizar una tirada de salvación de Constitución con CD 15 para acabar con el efecto de esas heridas si la supera. Como alternativa, la criatura herida u otra que se encuentre a 1,5 m o menos de ella podrá usar una acción para realizar una prueba de Sabiduría (Medicina) con CD 15 y acabar con el efecto de las heridas si la supera.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_f0e511db536bffb9$::jsonb and revision=3) union all select 'ece:official:equipment:es:82bec804f111fbf655ff7dcf' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:82bec804f111fbf655ff7dcf' and payload#>'{features}'=$verify_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_4ca76cc6ddf1af62$::jsonb and revision=3) union all select 'ece:official:equipment:es:837132a2b546795dcbf8cd3c' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:837132a2b546795dcbf8cd3c' and payload#>'{features}'=$verify_7193c7266114fc5c$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta diadema, podrás utilizar una acción para lanzar el conjuro rayo abrasador. Cuando lleves a cabo los ataques del conjuro, tu bonificador de ataque será de +5. La diadema no puede volver a emplearse de esta manera hasta el siguiente amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_7193c7266114fc5c$::jsonb and revision=3) union all select 'ece:official:equipment:es:8442091e560c1191cf13f5d2' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8442091e560c1191cf13f5d2' and payload#>'{features}'=$verify_d21d948ae4ba094c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este diminuto objeto parece una pluma. Existen diferentes tipos de fichas de pluma, cada uno con un efecto diferente de un solo uso. Tu GM elige el tipo de ficha o lo determina al azar.\n\n01–15 · Abanico 61–75 ·  · Bote cisne\n16–35 · Ancla 76–85 ·  · Látigo\n36–60 · Árbol 86–00 ·  · Pájaro\n\nAbanico. Si te encuentras en un bote o barco, puedes emplear una acción para tirar la ficha al aire hasta 3 m de altura. La ficha desaparecerá y un abanico gigante en movimiento ocupará su lugar. El abanico flota y crea un viento lo bastante fuerte como para henchir las velas de un barco y aumentar su velocidad en 7,5 km/h durante 8 horas. Como acción, puedes hacer que el abanico desaparezca.\n\nAncla. Puedes emplear una acción para tocar un bote o barco con la ficha. Durante las próximas 24 horas, la embarcación no podrá moverse de ninguna manera. Volver a tocarla con la ficha pone fin al efecto. Cuando acabe el efecto, la ficha desaparece.\n\nÁrbol. Debes estar al aire libre para poder usar esta ficha. Puedes emplear una acción para tocar con la ficha un espacio sin ocupar del suelo. La ficha desaparecerá y un roble no mágico ocupará su lugar. El árbol mide 18 m de alto, el diámetro de su tronco es de 1,5 m y las ramas de su copa cubren un radio de 6 m.\n\nBote cisne. Puedes emplear una acción para tocar con la ficha una masa de agua de al menos 18 m de diámetro. La ficha desaparecerá y un bote de 15 m de largo y 6 m de ancho con la forma de un cisne ocupará su lugar. El bote se autopropulsa y se desplaza por el agua a una velocidad de 9 km/h. Puedes emplear una acción mientras te encuentres en el barco para ordenarle moverse o girar hasta 90 grados. La embarcación puede transportar hasta treinta y dos criaturas Medianas o de menor tamaño. Una criatura Grande cuenta como cuatro criaturas Medianas, mientras que una criatura Enorme cuenta como nueve. El bote permanece durante 24 horas y después desaparece. Como acción, puedes hacer que el bote desaparezca.\n\nLátigo. Puedes emplear una acción para tirar la ficha a 3 m o menos de ti. La ficha desaparecerá y un látigo flotante ocupará su lugar. A continuación, podrás utilizar una acción adicional para realizar un ataque de conjuro cuerpo a cuerpo contra una criatura que esté a 3 m o menos del látigo, con un bonificador de ataque de +9. Si impacta, el objetivo recibe 1d6 + 5 de daño de fuerza.\n\nComo acción adicional durante tu turno, puedes mover el látigo hasta 6 m y repetir el ataque contra una criatura que se encuentre a 3 m o menos de ella. El látigo desaparecerá después de 1 hora, si usas una acción para hacerlo desaparecer o si estás incapaci- tado o mueres.\n\nPájaro. Puedes emplear una acción para tirar la ficha al aire a 1,5 m de altura. La ficha desaparecerá y un enorme pájaro multicolor ocupará su lugar. El pájaro tiene el perfil de un roc, pero obedece las órdenes sencillas que le des y no puede atacar. Puede transportar hasta 250 kg mientras vuela a su velocidad máxima (24 km/h y, como máximo, 216 km al día, con descansos de una hora cada 3 horas de vuelo) o 500 kg a la mitad de esa velocidad. El ave desaparece tras volar su distancia máxima durante un día o si sus puntos de golpe se reducen a 0. Como acción, puedes hacer que el pájaro desaparezca.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_d21d948ae4ba094c$::jsonb and payload#>'{rules,personalDescription}'=$verify_e30ceaaba51fd812$"Este pequeño objeto parece una pluma. Existen diferentes tipos de fichas de pluma, cada uno con un efecto de un solo uso diferente. El DM elige el tipo o lo determina al azar.\n\n01-20 - Ancla\n21-35 - Pájaro\n36-50 - Abanico\n51-65 - Barco cisne\n66-90 - Árbol\n91-00 - Látigo \nAncla. Puedes emplear una acción para tocar un bote o barco con la ficha. Durante las próximas 24 horas, la nave no podrá moverse de ninguna manera. Volver a tocarla con la ficha termina el efecto. Cuando acabe, la ficha desaparece.\n Pájaro. Puedes utilizar una acción para tirar la ficha al aire 5 pies. Desaparecerá y será sustituida por un enorme pájaro multicolor. Tiene el perfil de un roe (ver Monster Manual), pero obedece las órdenes sencillas que le des y no puede atacar. Es capaz de transportar hasta 100 libras volando a máxima velocidad (16 millas por hora, máximo de 144 millas al día, con descansos de una hora cada 3 horas de vuelo) o 1.000 libras a mitad de velocidad. El ave desaparece tras volar su distancia máxima durante un día o si sus puntos de golpe descienden a O. Puedes desconvocar al pájaro utilizando una acción. \nAbanico. Si estás en un barco o bote, puedes usar una acción para tirar la ficha al aire a 10 pies de altura. Desaparecerá, dando paso a un abanico gigante en movimiento. Este flota y crea un viento lo suficientemente fuerte como para llenar las velas del barco, aumentando su velocidad en 5 millas por hora durante 8 horas. Puedes desconvocar el abanico utilizando una acción. \nBote cisne. Puedes emplear una acción para tocar con la ficha una masa de agua de al menos 60 pies de diámetro. La ficha desaparecerá y en su lugar aparecerá un bote de 50 pies de largo y 20 de ancho con forma de cisne. El bote es autopropulsado y se mueve por el agua a una velocidad de 6 millas por hora. Puedes utilizar una acción mientras estás en el barco para ordenarle moverse o girar 90 grados. El bote puede alojar hasta 32 criaturas Medianas o de menor tamaño. Una criatura Grande cuenta como cuatro Medianas y una Enorme como nueve. El barco permanece durante 24 horas y luego se desvanece. Puedes desconvocarlo utilizando una acción. \nArbol. Debes estar al aire libre para poder usar esta ficha. Puedes emplear una acción para tocar un espacio desocupado del suelo con la ficha. Desaparecerá y en su Jugar surgirá de la nada un roble no mágico. El árbol tiene 60 pies de altura y 5 pies de diámetro y las ramas de su copa cubren 20 pies de radio. \nLátigo. Puedes utilizar una acción para tirar la ficha a un punto situado a 10 pies o menos de distancia. Desaparecerá y en su lugar flotará un látigo. Después, podrás usar una acción adicional para realizar un ataque de conjuro cuerpo a cuerpo contra una criatura que se encuentre a 10 pies del arma, con un bonificador de ataque de +9. Si impactas, el objetivo recibe 1d6 + 5 de daño de fuerza. Puedes utilizar una acción adicional en tu turno para mover el látigo hasta 20 pies y repetir el ataque contra una criatura situada a 10 pies o menos de él. El arma desaparece tras 1 hora, cuando uses tu acción para desconvocarla, o cuando quedes incapacitado o mueras."$verify_e30ceaaba51fd812$::jsonb and revision=3) union all select 'ece:official:equipment:es:844e28dd6ac8a83fb3ca8ef0' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:844e28dd6ac8a83fb3ca8ef0' and payload#>'{description}'=$verify_ca5e6004250fdca5$"Objeto · Precio base · Peso\nLibro de conjuros · 50 po · 3 lb\n\nLibro de conjuros. Indispensable para los magos, un libro de conjuros es un tomo encuadernado en cuero con 100 páginas de vitela en blanco, adecuadas para escribir conjuros.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_ca5e6004250fdca5$::jsonb and payload#>'{features}'=$verify_aa29c45791edda23$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Libro de conjuros. Indispensable para los magos, un libro de conjuros es un tomo encuadernado en cuero con 100 páginas de vitela en blanco, adecuadas para escribir conjuros.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_aa29c45791edda23$::jsonb and payload#>'{rules,definition,description}'=$verify_d0cdc14ec2a16eb6$[{"id":"official-table","rows":[["Libro de conjuros","50 po","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Libro de conjuros. Indispensable para los magos, un libro de conjuros es un tomo encuadernado en cuero con 100 páginas de vitela en blanco, adecuadas para escribir conjuros.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_d0cdc14ec2a16eb6$::jsonb and revision=3) union all select 'ece:official:equipment:es:85b343f16d824ce798cbb857' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:85b343f16d824ce798cbb857' and payload#>'{features}'=$verify_70b341cbb9386adf$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Una flecha asesina es un arma mágica diseñada para matar a un tipo concreto de criatura. Algunas son más específicas que otras. Por ejemplo, hay tanto flechas asesinas de dragones como flechas asesinas de dragones azules. Si una criatura que pertenezca al tipo, raza o grupo asociado con una flecha asesina recibe daño de ella, deberá realizar una tirada de salvación de Constitución con CD 17; sufrirá 6d10 de daño perforante adicional si la falla o la mitad del daño adicional si la supera.\n\nEn cuanto una flecha asesina inflige su daño adicional a una criatura, se vuelve una flecha no mágica.\n\nExisten otros tipos de municiones similares, como los virotes asesinos para ballestas, aunque las flechas son las más comunes.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_70b341cbb9386adf$::jsonb and revision=3) union all select 'ece:official:equipment:es:86cffac954a9cc099e37eccf' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:86cffac954a9cc099e37eccf' and payload#>'{description}'=$verify_00e28e9a737512ca$"Objeto · Precio base · Peso\nAlforjas · 4 po · 8 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_00e28e9a737512ca$::jsonb and payload#>'{rules,definition,description}'=$verify_c6457c54b8f6c83d$[{"id":"official-table","rows":[["Alforjas","4 po","8 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_c6457c54b8f6c83d$::jsonb and revision=3))t;